package me.matsumo.fanbox.core.logs.category

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

// This class is automatically generated by generate-log-classes.
sealed interface WelcomeLog : LogCategory {

    class FirstOpen internal constructor() : WelcomeLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "welcome")
            put("event_name", "first_open")
        }
    }

    class LoggedIn internal constructor() : WelcomeLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "welcome")
            put("event_name", "logged_in")
        }
    }

    class LoggedOut internal constructor() : WelcomeLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "welcome")
            put("event_name", "logged_out")
        }
    }

    class CompletedOnboarding internal constructor(
        startAt: String,
        endAt: String,
        neededTime: Long,
    ) : WelcomeLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "welcome")
            put("event_name", "completed_onboarding")
            put("start_at", startAt)
            put("end_at", endAt)
            put("needed_time", neededTime)
        }
    }

    class LoginChecked internal constructor(
        method: String,
        trigger: String,
        result: String,
        errorKind: String,
    ) : WelcomeLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "welcome")
            put("event_name", "login_checked")
            put("method", method)
            put("trigger", trigger)
            put("result", result)
            put("error_kind", errorKind)
        }
    }

    class WebLoginClosed internal constructor(lastHost: String, isLoggedIn: Boolean) : WelcomeLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "welcome")
            put("event_name", "web_login_closed")
            put("last_host", lastHost)
            put("is_logged_in", isLoggedIn)
        }
    }

    companion object {
        // アプリを初めて開いたときのログ
        fun firstOpen() = FirstOpen()

        // ログインしたときのログ
        fun loggedIn() = LoggedIn()

        // ログアウトしたときのログ
        fun loggedOut() = LoggedOut()

        // オンボーディングを完了したときのログ
        fun completedOnboarding(
            startAt: String,
            endAt: String,
            neededTime: Long,
        ) = CompletedOnboarding(startAt, endAt, neededTime)

        // ログイン画面で、ログインできたかを確かめたときのログ
        fun loginChecked(
            method: String,
            trigger: String,
            result: String,
            errorKind: String,
        ) = LoginChecked(method, trigger, result, errorKind)

        // WebView のログイン画面を閉じたときのログ
        fun webLoginClosed(lastHost: String, isLoggedIn: Boolean) = WebLoginClosed(lastHost, isLoggedIn)
    }
}
